import{_ as o,o as t,c as r,j as e,a as s}from"./chunks/framework.44aEvdQQ.js";const v=JSON.parse('{"title":"Operating Values vs Core Values","description":"","frontmatter":{"title":"Operating Values vs Core Values","order":3},"headers":[],"relativePath":"about/chapters/03-operating-values-vs-core-values.md","filePath":"about/chapters/03-operating-values-vs-core-values.md"}'),n={name:"about/chapters/03-operating-values-vs-core-values.md"};function i(l,a,u,h,d,c){return t(),r("div",null,[...a[0]||(a[0]=[e("h4",{id:"behaviors-not-words",tabindex:"-1"},[s("Behaviors, not words "),e("a",{class:"header-anchor",href:"#behaviors-not-words","aria-label":'Permalink to "Behaviors, not words"'},"​")],-1),e("p",null,"Core values are verbs or nouns you claim are adjectives, that describe your behavior. They're worth having, worth publishing on your website, and worth instilling in your people. They're good but operating values are more useful. Life would be easier if we could measure behaviors, not words. Doing so would reveal our actual values, how we act when things go wrong, how we act when things go our way. Daily decisions reveal our operating values, and if we don't like the optics we should change to leave a better taste in mouths. Introspection is an asset, but when we dwell only in the theoretical — the core values — we obsess over appearance and neglect what we embody in the everyday. What use is a compass if we always prefer to avoid true north because we just feel like we know a shortcut?",-1),e("p",null,"Core values are philosophical ideals; operating values define what we stand for when things do not go to plan. Experience teaches you that being useful is preferable to being perfect. Operating values determine everything from hiring (and firing) to saying no to revenue that does not add value. Behaviors compound over time to shape the culture (good or ugly) of your firm. We plan for success by facing the truth and setting deliberate standards for our behavior up-front.",-1)])])}const w=o(n,[["render",i]]);export{v as __pageData,w as default};
